import {STUDIES} from './atlas/catalog.js';
const NS='http://www.w3.org/2000/svg';
const hero=document.querySelector('#atlas-hero-orbits');
for(let i=0;i<44;i++){const ellipse=document.createElementNS(NS,'ellipse');ellipse.setAttribute('cx','300');ellipse.setAttribute('cy','300');ellipse.setAttribute('rx',String(200+Math.sin(i*.14)*18));ellipse.setAttribute('ry',String(38+Math.sin(i*.17)*16));ellipse.setAttribute('transform',`rotate(${i/44*180} 300 300)`);ellipse.setAttribute('fill','none');ellipse.setAttribute('stroke',i%7===0?'#dfff00':'#70f4ed');ellipse.setAttribute('stroke-width',i%7===0?'1.4':'.8');ellipse.setAttribute('stroke-opacity',String(.3+i*.013));hero.append(ellipse)}
const grid=document.querySelector('#atlas-mosaic'),search=document.querySelector('#atlas-search'),savedFilter=document.querySelector('#atlas-saved-filter');
let family='All',savedOnly=false,saved=new Set();
try{const value=JSON.parse(localStorage.getItem('atlas-favorites')||'[]');if(Array.isArray(value))saved=new Set(value.filter(id=>STUDIES.some(study=>study.id===Number(id))).map(Number))}catch{/* The gallery remains usable without storage. */}
const bookmark='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 4h11v16L12 16.5 6.5 20Z"/></svg>';
const fixed=(number)=>Number(number).toFixed(2);
function orbitMarkup(study){let lines='';for(let i=0;i<25;i++)lines+=`<ellipse cx="300" cy="208" rx="${182+Math.sin(i*.2)*15}" ry="${43+Math.sin(i*.3)*20}" transform="rotate(${i/25*180} 300 208)" stroke="${i%6===0?study.foreground:study.accent}" stroke-opacity="${.2+i*.022}" stroke-width="1" fill="none"/>`;return lines}
function thumbnail(study){const a=study.accent,b=study.background,f=study.foreground,id=study.id;let shape='';
  if(id===1){shape=`<defs><radialGradient id="thumb-glow-${id}"><stop stop-color="${a}" stop-opacity=".28"/><stop offset="1" stop-color="${b}" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="210" r="190" fill="url(#thumb-glow-${id})"/>`;for(let i=0;i<25;i++)shape+=`<ellipse cx="300" cy="210" rx="${85+i*4.6}" ry="${24+i*1.8}" transform="rotate(-25 300 210)" fill="none" stroke="${a}" stroke-opacity="${.15+i*.027}"/>`;shape+=`<circle cx="300" cy="210" r="74" fill="${b}"/><path d="M216 182a88 88 0 0 1 166 57" fill="none" stroke="${a}" stroke-width="4"/>`}
  else if(id===2){for(let i=0;i<24;i++)shape+=`<ellipse cx="300" cy="145" rx="24" ry="96" transform="rotate(${i*15} 300 210)" fill="${a}" fill-opacity=".11" stroke="${a}" stroke-opacity=".55"/>`;shape+=`<circle cx="300" cy="210" r="18" fill="${f}"/>`}
  else if(id===3){for(let i=0;i<12;i++){const s=1-i*.063;shape+=`<rect x="${300-215*s}" y="${210-145*s}" width="${430*s}" height="${290*s}" fill="none" stroke="${i%3===0?a:f}" stroke-opacity="${.3+i*.05}" stroke-width="${1+i*.08}" transform="rotate(${i*3} 300 210)"/>`}}
  else if(id===4){for(let i=0;i<12;i++){const s=1-i*.065;shape+=`<path d="M${300-210*s} ${210+160*s}V${210-35*s}a${210*s} ${150*s} 0 0 1 ${420*s} 0v${195*s}" fill="none" stroke="${a}" stroke-width="${2.7-i*.14}" transform="rotate(${i*1.5-8} 300 210)"/>`}}
  else if(id===5){for(let i=0;i<42;i++){const y=90+i*6;shape+=`<path d="M-40 ${y}C150 ${y-150},230 ${y+150},330 ${y+20}S510 ${y-130},650 ${y+50}" fill="none" stroke="${i%3===0?f:a}" stroke-opacity="${.22+(i%9)*.06}" stroke-width="1.2"/>`}}
  else if(id===6){shape=`<text x="58" y="207" font-family="Display,sans-serif" font-size="155" font-weight="700" fill="${f}">TYPE</text><text x="108" y="330" font-family="Display,sans-serif" font-size="155" font-weight="700" fill="${a}" transform="rotate(-5 300 240)">FORCE</text><path d="M485 92v48m-24-24h48" stroke="${a}" fill="none"/>`}
  else if(id===7){shape=`<g fill="none" stroke="${a}" stroke-opacity=".24">${[0,1,2,3].map(i=>`<ellipse cx="300" cy="210" rx="${230-i*22}" ry="${125-i*18}" transform="rotate(-15 300 210)"/>`).join('')}</g><text x="53" y="292" font-family="Display,sans-serif" font-size="225" font-weight="700" fill="${a}" textLength="495" lengthAdjust="spacingAndGlyphs">FLOW</text><circle cx="415" cy="185" r="60" fill="none" stroke="${f}" stroke-width="1.4"/><circle cx="415" cy="185" r="79" fill="none" stroke="${f}" stroke-opacity=".45"/>`}
  else if(id===8){shape=`<text x="58" y="168" font-family="Display,sans-serif" font-size="100" font-weight="700" fill="${a}" transform="rotate(-9 70 100)">SLOW</text><text x="260" y="253" font-family="Display,sans-serif" font-size="125" font-weight="700" fill="${f}" transform="rotate(8 260 253)">SOFT</text><text x="94" y="330" font-family="Display,sans-serif" font-size="124" font-weight="700" fill="#f4f0e2">AIR</text><path d="M30 280C170 150 380 370 575 260" fill="none" stroke="${f}" stroke-opacity=".3"/>`}
  else if(id===9){shape=`<circle cx="406" cy="207" r="125" fill="none" stroke="${a}"/><text x="42" y="160" font-family="Display,sans-serif" font-size="125" font-weight="700" fill="${f}">READ</text><text x="123" y="259" font-family="Display,sans-serif" font-size="127" font-weight="700" fill="${a}">BETWEEN</text><text x="42" y="357" font-family="Display,sans-serif" font-size="120" font-weight="700" fill="${f}">LINES.</text>`}
  else if(id===10){for(let i=11;i>=0;i--)shape+=`<text x="${45+i*4}" y="${250+i*4}" font-family="Display,sans-serif" font-size="155" font-weight="700" fill="${i===0?f:'none'}" stroke="${a}" stroke-opacity="${i===0?1:.18}" stroke-width=".7" textLength="460" lengthAdjust="spacingAndGlyphs">REMAINS.</text>`}
  else if(id===11){const balls=[[150,240,77],[340,270,95],[433,119,34],[249,122,42],[83,102,22]];shape=`<path d="M42 350h516" stroke="${f}" stroke-opacity=".5"/>`+balls.map(([x,y,r],i)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${i%2?a:f}"/><path d="M${x-r*.5} ${y-r*.5}q${r*.3} ${-r*.35} ${r*.7} 0" stroke="${b}" fill="none" stroke-width="1.4"/>`).join('')}
  else if(id===12){for(let y=0;y<8;y++)for(let x=0;x<12;x++){const px=75+x*41,py=80+y*36+Math.sin(x*.5+y*.2)*17;if(x<11)shape+=`<path d="M${px} ${py}l41 ${Math.sin((x+1)*.5+y*.2)*17-Math.sin(x*.5+y*.2)*17}" stroke="${a}" stroke-opacity=".3"/>`;shape+=`<circle cx="${px}" cy="${py}" r="${3+Math.sin(x*.7+y)*2}" fill="${a}"/>`}}
  else if(id===13){for(let i=0;i<22;i++){const y=80+i*11;shape+=`<path d="M83 ${y}C170 ${y-80},270 ${y+105},520 ${y-24}" fill="none" stroke="${a}" stroke-opacity=".8" stroke-width=".85"/>`}for(let i=0;i<28;i++){const x=83+i*16;shape+=`<path d="M${x} ${80+Math.sin(i*.2)*15}C${x+65} 130,${x-75} 260,${x-16} 329" fill="none" stroke="${a}" stroke-opacity=".35" stroke-width=".6"/>`}}
  else if(id===14){for(let i=0;i<21;i++){const y=30+i*18;shape+=`<path d="M30 ${y}C170 ${y},174 ${210+(y-210)*.2},300 210C426 ${210+(y-210)*.2},440 ${y},570 ${y}" stroke="${a}" stroke-opacity=".38" fill="none"/>`}shape+=`<circle cx="232" cy="210" r="26" fill="${a}"/><circle cx="368" cy="210" r="26" fill="${f}"/><path d="M220 210h24m-12-12v24M356 210h24" stroke="${b}" stroke-width="2"/>`}
  else if(id===15){for(let i=0;i<5;i++)shape+=`<ellipse cx="300" cy="210" rx="${75+i*37}" ry="${35+i*20}" transform="rotate(-23 300 210)" fill="none" stroke="${f}" stroke-opacity=".3"/>`;shape+=`<circle cx="300" cy="210" r="35" fill="${a}"/><circle cx="422" cy="141" r="16" fill="#e5a4e7"/><circle cx="173" cy="288" r="26" fill="${f}"/><circle cx="490" cy="247" r="9" fill="${a}"/>`}
  else if(id===16){shape=`<rect x="82" y="90" width="250" height="88" rx="44" fill="${a}"/><circle cx="287" cy="134" r="34" fill="${b}"/><rect x="248" y="235" width="260" height="81" rx="40.5" fill="none" stroke="${f}" stroke-width="2"/><circle cx="292" cy="275" r="29" fill="${f}"/><circle cx="145" cy="276" r="52" fill="${a}"/><path d="m128 277 14 14 23-30" stroke="${b}" stroke-width="4" fill="none"/>`}
  else if(id===17){for(let i=0;i<5;i++)shape+=`<rect x="${58+i*101}" y="${70+i*21}" width="82" height="${255-i*20}" rx="${i*12}" fill="${i%2?a:f}" fill-opacity="${.3+i*.15}" transform="rotate(${i*4-8} ${99+i*101} 210)"/>`}
  else if(id===18){const boxes=[[60,65,210,160],[287,65,113,76],[416,65,123,160],[287,156,113,69],[60,243,113,106],[189,243,211,106],[416,243,123,106]];shape=boxes.map(([x,y,w,h],i)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${i%2?3:18}" fill="${i%3===0?a:f}" fill-opacity="${i%3===0?1:.1+i*.06}"/>`).join('')}
  else if(id===19){for(let i=0;i<8;i++)shape+=`<path d="M${-70+i*20} 420C${100+i*10} ${30+i*20},${440-i*20} ${70+i*27},${650-i*18} 420Z" fill="${i%2?a:f}" fill-opacity="${.1+i*.085}"/>`;shape+=`<circle cx="400" cy="125" r="48" fill="${a}"/>`}
  else{let random=id;for(let i=0;i<400;i++){random=(random*1664525+1013904223)>>>0;const t=random/4294967296*Math.PI*2;random=(random*1664525+1013904223)>>>0;const radius=Math.sqrt(random/4294967296)*157;const px=300+Math.cos(t)*radius*1.3,py=210+Math.sin(t)*radius*.77;shape+=`<circle cx="${fixed(px)}" cy="${fixed(py)}" r="${i%7===0?2.2:.7}" fill="${i%7===0?f:a}" fill-opacity="${.22+(i%9)*.08}"/>`}}
  return `<svg viewBox="0 0 600 420" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">${shape}</svg>`;
}
function filtered(){const query=search.value.trim().toLowerCase();return STUDIES.filter(study=>(family==='All'||study.family===family)&&(!savedOnly||saved.has(study.id))&&(!query||[study.title,study.family,study.description,...study.tags].join(' ').toLowerCase().includes(query)))}
function syncFavorites(){document.querySelector('#atlas-saved-count').textContent=String(saved.size).padStart(2,'0');document.querySelectorAll('[data-save-study]').forEach(button=>{const id=Number(button.dataset.saveStudy),study=STUDIES.find(s=>s.id===id),active=saved.has(id);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',`${active?'Unsave':'Save'} ${study.title}`)})}
function render(){const focused=document.activeElement?.dataset.saveStudy,oldButtons=[...grid.querySelectorAll('[data-save-study]')],oldIndex=oldButtons.findIndex(b=>b.dataset.saveStudy===focused),items=filtered();grid.replaceChildren();for(const study of items){const article=document.createElement('article');article.className='atlas-card'+([1,7,13,20].includes(study.id)?' is-wide':'');article.style.setProperty('--card-bg',study.background);article.style.setProperty('--card-fg',study.foreground);article.style.setProperty('--card-accent',study.accent);article.innerHTML=`<a class="atlas-card-link" href="atlas/${study.slug}.html" aria-label="Open ${study.title}, study ${String(study.id).padStart(2,'0')}"><div class="atlas-card-art">${thumbnail(study)}<span class="atlas-card-index">${String(study.id).padStart(2,'0')}</span><span class="atlas-card-kind">${study.family} / Original study</span><span class="atlas-card-open" aria-hidden="true">↗</span></div><div class="atlas-card-caption"><h3>${study.title}</h3><span aria-hidden="true">↗</span></div><p class="atlas-card-tags">${study.tags.join(' / ')}</p></a><button type="button" class="atlas-bookmark" data-save-study="${study.id}" aria-label="Save ${study.title}" aria-pressed="false">${bookmark}</button>`;grid.append(article)}document.querySelector('#atlas-result-count').textContent=`${items.length} ${items.length===1?'perspective':'perspectives'} / ${family==='All'?'All studies':family}`;document.querySelector('#atlas-empty').hidden=items.length>0;document.querySelector('#atlas-empty-copy').textContent=savedOnly&&saved.size===0?'Save a study with its bookmark. Your keepers will be waiting here.':'Try another word, or look in another direction.';savedFilter.setAttribute('aria-pressed',String(savedOnly));document.querySelectorAll('[data-family]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.family===family)));syncFavorites();if(focused){const buttons=[...grid.querySelectorAll('[data-save-study]')];(buttons.find(b=>b.dataset.saveStudy===focused)||buttons[Math.min(oldIndex,buttons.length-1)]||savedFilter).focus({preventScroll:true})}}
grid.addEventListener('click',event=>{const button=event.target.closest('[data-save-study]');if(!button)return;const id=Number(button.dataset.saveStudy),study=STUDIES.find(s=>s.id===id),had=saved.has(id);had?saved.delete(id):saved.add(id);let stored=true;try{localStorage.setItem('atlas-favorites',JSON.stringify([...saved]))}catch{stored=false}const message=`${study.title} ${had?'removed from keepers':'saved'}${stored?'':' for this visit'}.`;document.querySelector('#atlas-announcement').textContent=message;if(window.PortfolioLab?.toast)window.PortfolioLab.toast(message);if(savedOnly)render();else syncFavorites()});
search.addEventListener('input',render);document.querySelectorAll('[data-family]').forEach(button=>button.addEventListener('click',()=>{family=button.dataset.family;render()}));savedFilter.addEventListener('click',()=>{savedOnly=!savedOnly;render()});document.querySelector('#atlas-reset-filters').addEventListener('click',()=>{family='All';savedOnly=false;search.value='';render();search.focus()});
function surprise(){const study=STUDIES[Math.floor(Math.random()*STUDIES.length)];location.href=`atlas/${study.slug}.html`}
document.querySelector('#atlas-surprise').addEventListener('click',surprise);document.querySelector('#atlas-surprise-again').addEventListener('click',surprise);
window.addEventListener('storage',event=>{if(event.key!=='atlas-favorites')return;try{const value=JSON.parse(event.newValue||'[]');if(Array.isArray(value)){saved=new Set(value.filter(id=>STUDIES.some(study=>study.id===Number(id))).map(Number));render()}}catch{/* Preserve valid state. */}});
render();
